var i=[{title:`Схема RAMP`,text:`RAMP розшифровується як Raise, Activate, Mobilize і Potentiate (підвищити, активувати, мобілізувати, потенціювати). Підвищте температуру тіла та дихання легкою активністю, «розбудіть» м’язи, які ви використаєте, контрольованими рухами, пройдіть амплітуди, які вам потрібні, а потім відпрацюйте вправу з поступово вищим зусиллям, яке все ще лишає вас свіжими. Фази можуть перекриватися. Вони не мусять бути чотирма довгими блоками.`},{title:`Старт на п’ять–десять хвилин`,text:`Почніть із легкої ходьби чи їзди на велосипеді. Додайте контрольовані присіди з вагою тіла, нахили з відведенням тазу, кола руками чи інші вправи, що відповідають заняттю. Перед важким підйомом виконайте один чи кілька легших підготовчих підходів. Перед інтервалами починайте з легших версій того самого руху, а не одразу зі спринту.`},{title:`Розминайтеся під завдання`,text:`Жим над головою може потребувати певного руху в плечах і легкого жимового підходу. Біг може потребувати легкого бігу та кількох поступових прискорень. Важка чи технічна робота часто потребує більше підготовки, ніж спокійна ходьба. Мета: відчути готовність, а вигадлива розминка, що вас втомлює, цієї мети не досягає.`},{title:`Де місце розтяжці`,text:`Довгі пасивні розтяжки безпосередньо перед вибуховою активністю можуть ненадовго знижувати результативність у деяких умовах. Коротка комфортна розтяжка не є автоматично шкідливою, але динамічна рухливість і поступова практика зазвичай важать більше безпосередньо перед силовою роботою, спринтом чи стрибками. Ніколи не розтягуйтеся через біль, щоб досягти якоїсь довільної глибини.`},{title:`Зведіть усе разом`,text:`Складіть розминку з рухів сьогоднішнього заняття, вашого рівня навички та простору: кілька хвилин легкої активності, потім легкі версії вашої першої вправи, з більшою підготовкою, коли робота важча чи швидша. Зараховуйте розминку до часу заняття.`}];var r=[{label:`ACE 2026: практичні поради щодо розтяжки`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Бібліотека вправ ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var l={sections:i,sources:r};export{l as default,i as sections,r as sources};